import datetime
try:
    today = datetime.date.fromisoformat(str(vars.get('now') or '')[:10])
    hol = ['2026-10-26', '2026-11-11', '2026-11-26', '2026-12-25', '2027-01-01']
    one = datetime.timedelta(days=1)
    def bd(d):
        return d.weekday() < 5 and d.isoformat() not in hol
    def fmt(d):
        return d.strftime('%A') + ' ' + d.isoformat()
    def last_bd(d):
        f = d + datetime.timedelta(days=4 - d.weekday())
        while not bd(f):
            f = f - one
        return f
    days = []
    d = today
    while len(days) < 12:
        d = d + one
        if bd(d):
            days.append(d)
    a1 = last_bd(today)
    if a1 <= today:
        a1 = last_bd(today + datetime.timedelta(days=7))
    lines = []
    for i in range(25):
        x = today + datetime.timedelta(days=i)
        tag = 'business day' if bd(x) else ('bank holiday' if x.isoformat() in hol else 'weekend')
        lines.append(fmt(x) + ': ' + tag + (' (today)' if i == 0 else ''))
    vars['date_facts'] = 'Today: ' + fmt(today) + '\nDeadline, early band (1 to 7 days late, 12th business day after today): ' + fmt(days[11]) + '\nDeadline, late band (8 to 45 days late, 7th business day after today): ' + fmt(days[6]) + '\nAttempt 1 date (last business day of this week, or of next week if today is that day): ' + fmt(a1) + '\nCalendar (weeks run Monday to Sunday):\n' + '\n'.join(lines)
except Exception:
    vars['date_facts'] = 'Not computed. Work the dates out from now: ' + str(vars.get('now'))

